package io.tornado.notification;
import io.tornado.persistence.*;import org.junit.jupiter.api.Test;import org.springframework.test.util.ReflectionTestUtils;import java.math.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;
class TelegramMessageFormatterTest{@Test void rendersTp1Sl1OutcomeFirstAndAllPersistedMilestonesInBody(){Coin c=new Coin("BTC","BTCUSDT");ReflectionTestUtils.setField(c,"id",1L);BestMethodMix m=new BestMethodMix(c,900,3,1,List.of("A","B","C"),List.of(1,1,1),List.of("A","B","C"),100,60,70,.5);MixTradeSimulation s=new MixTradeSimulation(c,m,Direction.UP,3,new BigDecimal("100"),TpSlLevels.defaults(),Instant.EPOCH);ReflectionTestUtils.setField(s,"id",9L);TelegramMessageFormatter f=new TelegramMessageFormatter();assertThat(f.open(s)).startsWith("⏳ TRADE PENDING · WAITING FOR TP1 / SL1").contains("TORNIDO MIX SIGNAL","TP1","TP2","TP3","SL1","SL2","SL3","Selected historical hit metric");var e=s.observeMilestones(new BigDecimal("100.6"),Instant.EPOCH.plusSeconds(2));assertThat(f.update(s,e.milestones())).startsWith("✅ TRADE SUCCESS · TP1 HIT FIRST").contains("✅ 1️⃣ TP1","✅ 2️⃣ TP2","⬜ 3️⃣ TP3","Outcome: ✅ TRADE SUCCESS · TP1 HIT FIRST").doesNotContain("TP2 TOUCHED");}@Test void failedOutcomeStaysAtTopWhileLaterTpMilestonesAreLogged(){Coin c=new Coin("BTC","BTCUSDT");ReflectionTestUtils.setField(c,"id",1L);BestMethodMix m=new BestMethodMix(c,900,3,1,List.of("A","B","C"),List.of(1,1,1),List.of("A","B","C"),100,60,70,.5);MixTradeSimulation s=new MixTradeSimulation(c,m,Direction.UP,3,new BigDecimal("100"),TpSlLevels.defaults(),Instant.EPOCH);s.observeMilestones(new BigDecimal("99.7"),Instant.EPOCH.plusSeconds(1),1L);var later=s.observeMilestones(new BigDecimal("100.6"),Instant.EPOCH.plusSeconds(2),2L);assertThat(new TelegramMessageFormatter().update(s,later.milestones())).startsWith("❌ TRADE FAILED · SL1 HIT FIRST").contains("❌ 1️⃣ SL1","✅ 1️⃣ TP1","✅ 2️⃣ TP2");}@Test void labelsHistoricalRateWithRepresentativeRankingTp(){Coin c=new Coin("BTC","BTCUSDT");ReflectionTestUtils.setField(c,"id",1L);BestMethodMix m=new BestMethodMix(c,900,3,1,List.of("A","B","C"),List.of(1,1,1),List.of("A","B","C"),100,60,70,.5,2,new BigDecimal(".50"));MixTradeSimulation s=new MixTradeSimulation(c,m,Direction.UP,3,new BigDecimal("100"),TpSlLevels.defaults(),Instant.EPOCH);assertThat(new TelegramMessageFormatter().open(s)).contains("Selected historical hit metric: TP2 (+0.5%)","Historical TP2 (+0.5%) Hit Rate");}}
